// ❌ OLD: Manual async effects in Solid suffer from out-of-order race conditions
// if userId changes quickly, and require manual loading/error signal boilerplate.
import { createSignal, createEffect } from 'solid-js';

export default function UserManual({ userId }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  createEffect(async () => {
    setLoading(true);
    const res = await fetch(`/api/users/${userId()}`);
    const data = await res.json();
    // ❌ Stale race condition: slow request for user 1 can overwrite fast user 2!
    setUser(data);
    setLoading(false);
  });

  return <div>{loading() ? 'Loading...' : user()?.name}</div>;
}

import { createResource, Suspense } from 'solid-js';

const fetchUser = async (id) => {
  const res = await fetch(`/api/users/${id}`);
  return res.json();
};

function UserProfile({ userId }) {
  // ✅ Automatically re-fetches when userId() changes; discards stale responses:
  const [user] = createResource(userId, fetchUser);
  return <h1>{user().name}</h1>;
}

export default function App({ userId }) {
  return (
    <Suspense fallback={<div>Loading user profile...</div>}>
      <UserProfile userId={userId} />
    </Suspense>
  );
}
